using System;
using System.Linq;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Game;
using Revora.Network.GamePackets;
internal static partial class CheckCandidateArenaLifecycle {
    static string FreshRosterSnapshot(GameState p,GameState[] players,GameState peer,GameState[] trainees){return Convert.ToString(Sql("SELECT json_build_object('prior',@prior::json,'profiles',(SELECT json_agg(r ORDER BY uid) FROM (SELECT uid,owner,name,body,class,level,reborn,experience,atributes,strength,agility,spirit,vitality,mapid,x,y,conquerpoints,boundcps,money FROM entities WHERE uid=ANY(@uids))r),'items',(SELECT json_agg(r ORDER BY entityid,uid) FROM items r WHERE entityid=ANY(@uids)),'creation',(SELECT json_agg(r ORDER BY character_uid) FROM revora_character_creation r WHERE character_uid=ANY(@uids)),'starter',(SELECT json_agg(r ORDER BY uid,reborn,milestone) FROM revora_custom_starter_claims r WHERE uid=ANY(@uids)),'allowance',(SELECT json_agg(r ORDER BY uid) FROM revora_exp_ball_days r WHERE uid=ANY(@uids)),'evidence',(SELECT json_agg(r ORDER BY uid,achievement_id) FROM revora_achievement_evidence r WHERE uid=ANY(@uids)),'training',(SELECT json_agg(r ORDER BY uid) FROM revora_fresh_roster_training r))::text","prior",FreshSoloSnapshot(p,players,peer),"uids",trainees.Select(w=>(long)w.Entity.UID).ToArray()));}
    static void FreshRosterSave(GameState p,GameState[] players,GameState peer,GameState[] trainees){foreach(var who in players.Concat(new[]{peer}).Concat(trainees).Distinct())Require(EntityTable.SaveEntity(who));Sql("UPDATE revora_fresh_roster_probe SET snapshot=@snapshot","snapshot",FreshRosterSnapshot(p,players,peer,trainees));}
    static void FreshRosterJourney(string phase){
        var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);


        var peer=FreshContributor(Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_warrior_peer_probe WHERE done")),"FreshWar1");Server.GamePool=players.Concat(new[]{peer}).ToArray();Require(!peer.Fake && peer.Account.State==AccountTable.AccountState.Player && peer.Entity.Class==20 && peer.Entity.Level>=130 && p.Entity.Level>=130);



        var listExtra=new System.Collections.Generic.List<GameState>{players[1]};foreach(int slot in new[]{4,5,6,7}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));listExtra.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}GameState fire;
        if(phase.EndsWith("create")){
            Require((bool)Sql("SELECT to_regclass('revora_fresh_roster_probe') IS NULL") && FreshSoloSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_solo_probe WHERE stage=2")) && (long)Sql("SELECT count(*) FROM accounts WHERE lower(username)='freshfire1'")==0);fire=FreshStarterSession();fire.Account.Username="FreshFire1";fire.Account.Password=Guid.NewGuid().ToString("N");fire.Account.Insert();Require(fire.Account.Password=="");string message="";Require(EntityTable.CreateEntity(new EnitityCreate{Name="FreshFire1",Body=1003,Class=0},fire,ref message) && message=="ANSWER_OK");FreshContributorLoad(fire);Require(fire.Entity.Level==1 && fire.Entity.Class==100 && fire.Entity.Reborn==0);Call(Feature("RevoraStarterPack"),"OnLogin",fire);ItemHandler.UseItem(fire.Inventory.Objects.Single(i=>i.ID==727990),fire);Require(fire.Entity.BoundCps==50000 && fire.Entity.Money==1100000);Sql("CREATE TABLE revora_fresh_roster_probe(fire bigint,done boolean,snapshot text);INSERT INTO revora_fresh_roster_probe VALUES(@fire,false,NULL);CREATE TABLE revora_fresh_roster_training(uid bigint PRIMARY KEY,balls int,spent bigint,capped int)","fire",(long)fire.Entity.UID);
        }else fire=FreshContributor(Convert.ToUInt32(Sql("SELECT fire FROM revora_fresh_roster_probe")),"FreshFire1");
        listExtra.Add(fire);var trainees=listExtra.ToArray();Server.GamePool=players.Concat(new[]{peer}).Concat(trainees).Distinct().ToArray();Require(trainees.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)));
        if(phase.EndsWith("create")){foreach(var who in trainees){Sql("INSERT INTO revora_fresh_roster_training VALUES(@uid,0,0,0)","uid",(long)who.Entity.UID);System.Console.WriteLine("[fresh-roster] uid="+who.Entity.UID+" class="+who.Entity.Class+" level="+who.Entity.Level);}FreshRosterSave(p,players,peer,trainees);}
        else{
            Require(FreshRosterSnapshot(p,players,peer,trainees)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_roster_probe")));
            if(phase.EndsWith("train")){
                Require(!(bool)Sql("SELECT done FROM revora_fresh_roster_probe"));DateTime day=new DateTime(2041,11,1,12,0,0,DateTimeKind.Local);Feature("ExperienceConsumables").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>day));var timer=System.Diagnostics.Stopwatch.StartNew();int batch=0;
                foreach(var who in trainees){int balls=(int)Sql("SELECT balls FROM revora_fresh_roster_training WHERE uid=@uid","uid",(long)who.Entity.UID);while(who.Entity.Level<70 && batch<240 && timer.Elapsed.TotalSeconds<210){day=new DateTime(2041,11,1,12,0,0,DateTimeKind.Local).AddDays(balls/10);who.Entity.Teleport(1002,304,435);uint cp=who.Entity.ConquerPoints;var old=who.Inventory.Objects.Select(i=>i.UID).ToArray();CareerBuy(who,723700);var ball=who.Inventory.Objects.Single(i=>!old.Contains(i.UID));uint cost=cp-who.Entity.ConquerPoints;Require(cost==ConquerItemInformation.BaseInformations[723700].ConquerPointsWorth);
                    if(balls>0 && balls%10==0){day=day.AddDays(-1);byte level=who.Entity.Level;ulong xp=who.Entity.Experience;ItemHandler.UseItem(ball,who);Require(who.Entity.Level==level && who.Entity.Experience==xp && who.Inventory.ContainsUID(ball.UID));day=day.AddDays(1);Sql("UPDATE revora_fresh_roster_training SET capped=capped+1 WHERE uid=@uid","uid",(long)who.Entity.UID);}
                    byte before=who.Entity.Level;ulong beforeXp=who.Entity.Experience;ItemHandler.UseItem(ball,who);Require(!who.Inventory.ContainsUID(ball.UID) && (who.Entity.Level>before || who.Entity.Experience>beforeXp));balls++;batch++;Require((bool)Sql("SELECT used=@used AND day=@day FROM revora_exp_ball_days WHERE uid=@uid","used",balls%10==0?10:balls%10,"day",day.Year*10000+day.Month*100+day.Day,"uid",(long)who.Entity.UID));byte after=who.Entity.Level;ulong afterXp=who.Entity.Experience;uint afterCp=who.Entity.ConquerPoints;int bag=who.Inventory.Count;ItemHandler.UseItem(ball,who);Require(who.Entity.Level==after && who.Entity.Experience==afterXp && who.Entity.ConquerPoints==afterCp && who.Inventory.Count==bag);Require(EntityTable.SaveEntity(who));Sql("UPDATE revora_fresh_roster_training SET balls=@balls,spent=spent+@cost WHERE uid=@uid","balls",balls,"cost",(long)cost,"uid",(long)who.Entity.UID);Sql("UPDATE revora_fresh_roster_probe SET snapshot=@snapshot","snapshot",FreshRosterSnapshot(p,players,peer,trainees));}
                    System.Console.WriteLine("[fresh-roster] uid="+who.Entity.UID+" level="+who.Entity.Level+" balls="+balls);
                }
                if(trainees.All(w=>w.Entity.Level>=70)){
                    foreach(var who in new[]{trainees[4],fire}){if(who.Entity.Class==100){FreshClassicTalk(who,1004,10000,1);HeartTalk(who,10000,254);Require(who.Entity.Class==101);}if(who.Entity.Class==101){HeartTalk(who,10000,1);HeartTalk(who,10000,who==fire?(byte)254:(byte)253);}Require(who.Entity.Class==(who==fire?142:132));}Sql("UPDATE revora_fresh_roster_probe SET done=true");
                }
                FreshRosterSave(p,players,peer,trainees);
            }else Require(phase.EndsWith("reload") && (bool)Sql("SELECT done FROM revora_fresh_roster_probe") && trainees.All(w=>w.Entity.Level>=70) && trainees[4].Entity.Class==132 && fire.Entity.Class==142);
        }
        Require(FreshRosterSnapshot(p,players,peer,trainees)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_roster_probe")));System.Console.WriteLine("[career-process] "+phase+"-passed done="+Sql("SELECT done FROM revora_fresh_roster_probe")+" balls="+Sql("SELECT sum(balls) FROM revora_fresh_roster_training")+" cp="+Sql("SELECT sum(spent) FROM revora_fresh_roster_training"));System.Console.Out.Flush();Environment.Exit(0);
    }
}
